sudo -n tee /etc/nginx/conf.d/port-6700.conf >/dev/null <<'ANTRIEB_NGINX_EOF'
server {
    listen 6700 default_server;
    listen [::]:6700 default_server;
    server_name _;

    location = / {
        default_type text/plain;
        return 200 "nginx on node1 port 6700\n";
    }
}
ANTRIEB_NGINX_EOF
sudo -n chmod 0644 /etc/nginx/conf.d/port-6700.conf
sudo -n nginx -t

